/**
 * @title Field operations dashboard
 * @description For agriculture and field teams: today's weather, alerts that need action, task progress by crew, and a table of fields with crop, stage and moisture.
 * @route /operations
 * @height 960
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { Button } from "@/components/ui/button";
import { Alert } from "@/components/ui/feedback";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { SiteHeader } from "@/components/site-header";
import { Weather } from "@/components/weather";
import { CrewProgress } from "@/components/crew-progress";
import { FieldsTable } from "@/components/fields-table";

export default function Page() {
  return (
    <SidebarProvider>
      <DashboardSidebar current="Projects" variant="sidebar" />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Operations", href: "#" }, { label: "North farm" }]} actions={<Button size="sm" leadingIcon="plus">Log activity</Button>} />
        <div className="flex flex-1 flex-col gap-6 p-4 md:p-6">
          <div className="flex flex-col gap-1">
            <h1 className="text-heading-h2">North farm</h1>
            <p className="text-body-medium text-fg-secondary">12 fields · 486 ha · Season 2026 B</p>
          </div>
          <section aria-label="Alerts" className="grid gap-3 lg:grid-cols-2">
            <Alert tone="warning" title="Irrigation needed in 3 fields">Soil moisture in F-04, F-07 and F-11 is below 25%.</Alert>
            <Alert tone="info" title="Rain expected Thursday">Hold spraying in the east block until Friday.</Alert>
          </section>
          <div className="grid gap-4 lg:grid-cols-3">
            <Weather />
            <CrewProgress />
          </div>
          <FieldsTable />
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { BarChart3, Camera, Database, FileText, FolderKanban, Gauge, HelpCircle, LayoutDashboard, ListChecks, Search, Settings, Users } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton,
  SidebarMenuItem, SidebarRail,
} from "@/components/ui/sidebar";
import { BrandHeader } from "@/components/brand-header";
import { NavSecondary } from "@/components/nav-secondary";
import { NavUser } from "@/components/nav-user";

const main = [
  { title: "Dashboard", icon: LayoutDashboard }, { title: "Lifecycle", icon: ListChecks }, { title: "Analytics", icon: BarChart3 },
  { title: "Projects", icon: FolderKanban }, { title: "Team", icon: Users },
];
const documents = [{ title: "Data library", icon: Database }, { title: "Reports", icon: FileText }, { title: "Capture", icon: Camera }];
const secondary = [{ title: "Settings", url: "#", icon: Settings }, { title: "Get help", url: "#", icon: HelpCircle }, { title: "Search", url: "#", icon: Search }];

/** The app sidebar the dashboard, settings and table blocks share. Pass the current page's title. */
export function DashboardSidebar({ current = "Dashboard", variant = "inset" }: { current?: string; variant?: "sidebar" | "inset" }) {
  return (
    <Sidebar collapsible="icon" variant={variant} label="Main navigation">
      <SidebarHeader>
        <BrandHeader name="Acme Inc" detail="Workspace" logo={Gauge} />
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Main" className="contents">
          <SidebarGroup>
            <SidebarMenu>
              {main.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <SidebarGroup>
            <SidebarGroupLabel as="h2">Documents</SidebarGroupLabel>
            <SidebarMenu>
              {documents.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <NavSecondary items={secondary.map((s) => ({ ...s }))} className="mt-auto" />
        </nav>
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={{ name: "Jane Cooper", email: "jane@acme.com" }} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { GalleryVerticalEnd, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Logo, product name and a second line (plan or version) at the top of the sidebar. Links home. */
export function BrandHeader({ name = "Acme Docs", detail = "v4.0.0", logo = GalleryVerticalEnd }: { name?: string; detail?: string; logo?: LucideIcon }) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="lg" tooltip={name}>
          <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={logo} size={16} /></span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-label-medium text-fg-primary">{name}</span>
            <span className="truncate text-caption-default">{detail}</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Small links near the bottom of the sidebar (support, feedback). */
export function NavSecondary({ items, ...rest }: HTMLAttributes<HTMLDivElement> & { items: { title: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup {...rest}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton href={item.url} size="sm" tooltip={item.title}>
                <Icon name={item.icon} size={16} />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

import { CloudRain, CloudSun, Droplets, Sun, Wind, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";

const days: { day: string; icon: LucideIcon; label: string; hi: number; lo: number }[] = [
  { day: "Tue", icon: Sun, label: "Sunny", hi: 33, lo: 24 },
  { day: "Wed", icon: CloudSun, label: "Partly cloudy", hi: 31, lo: 24 },
  { day: "Thu", icon: CloudRain, label: "Rain", hi: 28, lo: 23 },
  { day: "Fri", icon: CloudSun, label: "Partly cloudy", hi: 30, lo: 23 },
];

export function Weather() {
  return (
    <section aria-labelledby="weather-title" className="flex flex-col gap-4 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)]">
      <h2 id="weather-title" className="text-heading-h4">Weather</h2>
      <div className="flex items-center gap-4">
        <Icon name={Sun} size={24} className="size-10 text-icon-warning" />
        <p className="flex flex-col"><span className="text-heading-h2 tabular-nums">32°C</span><span className="text-body-small text-fg-secondary">Sunny · feels like 36°</span></p>
      </div>
      <dl className="grid grid-cols-2 gap-2 text-body-small">
        <div className="flex items-center gap-2"><Icon name={Droplets} size={16} className="text-icon-secondary" /><dt className="text-fg-secondary">Humidity</dt><dd className="ms-auto tabular-nums">68%</dd></div>
        <div className="flex items-center gap-2"><Icon name={Wind} size={16} className="text-icon-secondary" /><dt className="text-fg-secondary">Wind</dt><dd className="ms-auto tabular-nums">12 km/h</dd></div>
      </dl>
      <ul className="grid grid-cols-4 gap-2 border-t border-line-default pt-4 text-center">
        {days.map((d) => (
          <li key={d.day} className="flex flex-col items-center gap-1">
            <span className="text-caption-default text-fg-secondary">{d.day}</span>
            <Icon name={d.icon} label={d.label} className="text-icon-secondary" />
            <span className="text-label-small tabular-nums">{d.hi}° <span className="text-fg-secondary">{d.lo}°</span></span>
          </li>
        ))}
      </ul>
    </section>
  );
}

import { Progress } from "@/components/ui/feedback";
import { Avatar } from "@/components/ui/display";

const crews = [
  { lead: "Ramon Cruz", task: "Harvest · F-02", value: 82, tone: "success" as const },
  { lead: "Ana Reyes", task: "Fertilizer · F-05", value: 54, tone: "brand" as const },
  { lead: "Leo Santos", task: "Irrigation repair · F-07", value: 25, tone: "warning" as const },
  { lead: "Mia Garcia", task: "Scouting · east block", value: 100, tone: "success" as const },
];

export function CrewProgress() {
  return (
    <section aria-labelledby="crews-title" className="flex flex-col gap-4 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)] lg:col-span-2">
      <div className="flex items-baseline justify-between gap-2">
        <h2 id="crews-title" className="text-heading-h4">Today's work by crew</h2>
        <span className="text-body-small text-fg-secondary">3 of 4 on track</span>
      </div>
      <ul className="flex flex-col gap-4">
        {crews.map((c) => (
          <li key={c.lead} className="flex items-center gap-3">
            <Avatar name={c.lead} decorative />
            <div className="min-w-0 flex-1"><Progress value={c.value} tone={c.tone} label={`${c.lead} — ${c.task}`} /></div>
          </li>
        ))}
      </ul>
    </section>
  );
}

"use client";
import { useState } from "react";
import { Badge } from "@/components/ui/feedback";
import { Table, type SortDir } from "@/components/ui/data";

type Field = { id: string; crop: string; area: number; stage: string; moisture: number; next: string };
const fields: Field[] = [
  { id: "F-01", crop: "Rice", area: 42, stage: "Tillering", moisture: 41, next: "Top-dress, Oct 14" },
  { id: "F-02", crop: "Rice", area: 38, stage: "Harvest", moisture: 33, next: "Harvest, today" },
  { id: "F-04", crop: "Corn", area: 55, stage: "Tasseling", moisture: 22, next: "Irrigate, today" },
  { id: "F-05", crop: "Corn", area: 47, stage: "V8", moisture: 36, next: "Fertilizer, in progress" },
  { id: "F-07", crop: "Sugarcane", area: 61, stage: "Grand growth", moisture: 19, next: "Irrigate, today" },
  { id: "F-09", crop: "Banana", area: 30, stage: "Flowering", moisture: 44, next: "Bagging, Oct 16" },
  { id: "F-11", crop: "Coffee", area: 24, stage: "Cherry", moisture: 24, next: "Irrigate, tomorrow" },
];
const moistureTone = (m: number) => (m < 25 ? "danger" : m < 35 ? "warning" : "success");
const moistureLabel = (m: number) => (m < 25 ? "Low" : m < 35 ? "Watch" : "Good");

export function FieldsTable() {
  const [sort, setSort] = useState<{ key: string; direction: SortDir } | null>({ key: "moisture", direction: "ascending" });
  return (
    <Table<Field>
      caption="Fields"
      rows={fields}
      rowKey={(f) => f.id}
      sort={sort}
      onSortChange={setSort}
      columns={[
        { key: "id", header: "Field", sortable: true, render: (f) => <a href="#" className="rounded-sm text-label-medium text-fg-brand underline-offset-2 hover:underline focus-visible:focus-ring">{f.id}</a> },
        { key: "crop", header: "Crop", sortable: true },
        { key: "area", header: "Area (ha)", numeric: true, sortable: true },
        { key: "stage", header: "Stage" },
        { key: "moisture", header: "Soil moisture", sortable: true, render: (f) => <span className="flex items-center gap-2"><span className="tabular-nums">{f.moisture}%</span><Badge tone={moistureTone(f.moisture)}>{moistureLabel(f.moisture)}</Badge></span> },
        { key: "next", header: "Next action" },
      ]}
    />
  );
}
